import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

test.describe("Upload vendor documents", () => {
  test(
    "A file of exactly 10 MiB is accepted",
    { tag: "@DOC-05" },
    async ({ apiAs }) => {
      // Background: signed in as member, vendor in status "draft"
      const member = await apiAs("member");
      const uniqueSuffix = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("DOC05 Vendor"),
          category: "software",
          contact_email: `doc05-${uniqueSuffix}@vendor.test`,
        },
      });
      expect(vendorResponse.status()).toBe(201);
      const vendor = await vendorResponse.json();
      expect(vendor.status).toBe("draft");

      // When I upload a text file of exactly 10 MiB as kind "contract"
      const buffer = Buffer.alloc(TEN_MIB, "a");
      const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "contract",
          file: {
            name: `contract-${uniqueSuffix}.txt`,
            mimeType: "text/plain",
            buffer,
          },
        },
      });

      // Then the response status is 201
      expect(response.status()).toBe(201);
    },
  );
});
